sys_script_client.script:
function onLoad() {
    //Type appropriate comment here, and begin script below
    if (typeof window.AMPHierarchy-- - 'undefined') {
        window.AMPHierarchy = {
            clearFields: function(fields) {
                if (!fields || !fields.length) {
                    return;
                }
                fields.forEach(function(field) {
                    try {
                        if (g_form && g_form.setValue) {
                            g_form.setValue(field, '');
                        }
                    } catch (e) {
                        console.log('Could not clear field: ' + field, e);
                    }
                });
            },
            clearBelowFmc: function() {
                this.clearFields([
                    'u_complex',
                    'u_property',
                    'u_city',
                    'u_state',
                    'u_zip'
                ]);
            },
            clearBelowComplex: function() {
                this.clearFields([
                    'u_property',
                    'u_city',
                    'u_state',
                    'u_zip'
                ]);
            },
            clearBelowProperty: function() {
                this.clearFields([
                    'u_city',
                    'u_state',
                    'u_zip'
                ]);
            }
        };
    }
}
